package au.edu.uow.csci318.assessment.domain;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class AssessmentTest{@Test void rejectsBadWeight(){assertThrows(IllegalArgumentException.class,()->new Assessment(UUID.randomUUID(),UUID.randomUUID(),"A","Essay",101d,null,null,null,60,null));}@Test void completionIsNotRepeatable(){var a=new Assessment(UUID.randomUUID(),UUID.randomUUID(),"A","Essay",20d,null,null,null,60,null);a.markCompleted();assertThrows(IllegalStateException.class,a::markCompleted);}@Test void rejectsNegativeWorkload(){var a=new Assessment(UUID.randomUUID(),UUID.randomUUID(),"A","Essay",20d,null,null,null,60,null);assertThrows(IllegalArgumentException.class,()->a.changeEstimatedWorkload(-1));}@Test void acceptsAnnualTeachingWeek(){var a=new Assessment(UUID.randomUUID(),UUID.randomUUID(),"Innovation Fair","Presentation",5d,null,26,null,60,null);assertEquals(26,a.getDueWeek());assertThrows(IllegalArgumentException.class,()->a.changeDeadline(null,53));}@Test void editsManualAssessmentDetails(){var a=new Assessment(UUID.randomUUID(),UUID.randomUUID(),"Draft","Essay",20d,null,null,null,60,null);a.updateDetails("Final report","Report",40d,java.time.LocalDate.of(2026,9,20),9,"Submit online",180,Assessment.Priority.HIGH);assertEquals("Final report",a.getTitle());assertEquals("Report",a.getType());assertEquals(180,a.getEstimatedMinutes());assertEquals(Assessment.Priority.HIGH,a.getPriority());}}
